local config = {
  str_homestory_N19chuanshanjia_90010101_1_dialog_content = "Cloud Gardens cukup ramai akhir-akhir ini.",
  str_homestory_N19chuanshanjia_90010101_2_dialog_content = "Benar? Sepertinya ada lebih banyak hewan di sini daripada sebelumnya.",
  str_homestory_N19chuanshanjia_90010101_3_dialog_content = "Tapi tahukah kamu, aku masih penasaran dengan makhluk bersisik berlapis baja yang selalu dibicarakan semua orang. Apa itu disebut lagi?",
  str_homestory_N19chuanshanjia_90010101_4_dialog_content = "Itu <color=#FFB400>Pangalo Litik</color>?",
  str_homestory_N19chuanshanjia_90010101_5_dialog_content = "Ya!",
  str_homestory_N19chuanshanjia_90010101_6_dialog_content = "Mereka tampaknya mampu menggali melalui gunung dan tanah. Memukau.",
  str_homestory_N19chuanshanjia_90010101_7_dialog_content = "Suara apa itu?",
  str_homestory_N19chuanshanjia_90010101_8_dialog_content = "Dengan cara itu!",
  str_homestory_N19chuanshanjia_90010101_9_dialog_content = "Ditutupi sisik dari ujung kepala hingga ujung kaki, dengan ekor yang sangat besar... Mungkinkah itu Pangalo tepat di depan kita?!",
  str_homestory_N19chuanshanjia_90010101_10_dialog_content = "Halo.",
  str_homestory_N19chuanshanjia_90010101_11_dialog_content = "Apakah kalian berdua akrab dengan tempat ini, kebetulan? Hmm, menurut pengetahuan dan pengalaman saya selama bertahun-tahun...",
  str_homestory_N19chuanshanjia_90010101_12_dialog_content = "Saya hanya bisa berasumsi bahwa Anda yang bertanggung jawab di sini, ya?",
  str_homestory_N19chuanshanjia_90010101_13_dialog_content = "Bagaimana kamu tahu?",
  str_homestory_N19chuanshanjia_90010101_14_dialog_content = "T-Tunggu, Vice, Anda dapat mendengar pikirannya juga?",
  str_homestory_N19chuanshanjia_90010101_15_dialog_content = "Apa yang Anda maksud dengan \"pikiran\"? Ini jelas berbicara kepada kita ...",
  str_homestory_N19chuanshanjia_90010101_16_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_17_dialog_content = "<size=65>Ya ampun itu berbicara!</size>",
  str_homestory_N19chuanshanjia_90010101_18_dialog_content = "Saya memang berbicara, ya.",
  str_homestory_N19chuanshanjia_90010101_19_dialog_content = "Dan sebagai catatan, nama saya adalah <color=#FFB400>Sahn</color>. Tolong jangan menyebut saya sebagai \"itu\" mulai sekarang, terima kasih.",
  str_homestory_N19chuanshanjia_90010101_20_dialog_content = "Ah! Namanya Sahn!",
  str_homestory_N19chuanshanjia_90010101_21_dialog_content = "Itu \"miliknya\", bukan \"miliknya\"! Sigh, saya dapat mengatakan bahwa Anda masih muda untuk jenis Anda, tapi tolong tunjukkan orang tua Anda sedikit lebih hormat.",
  str_homestory_N19chuanshanjia_90010101_22_dialog_content = "Aku benar-benar minta maaf. Dilihat dari jenggot panjang dan tebal Anda, saya yakin Anda memiliki kebijaksanaan dan pengalaman bertahun-tahun untuk dibagikan.",
  str_homestory_N19chuanshanjia_90010101_23_dialog_content = "Hewan yang bisa berbicara... Mungkinkah dia salah satunya <color=#FFB400>setengah manusia</color> dari legenda?",
  str_homestory_N19chuanshanjia_90010101_24_dialog_content = "Legenda?",
  str_homestory_N19chuanshanjia_90010101_25_dialog_content = "Apa yang terjadi dengan demi-human?",
  str_homestory_N19chuanshanjia_90010101_26_dialog_content = "*Batuk* Er, kamu harus memaafkan temanku, Sahn. Saya pikir itu hanya karena sudah lama sejak dia melihat Pangalo Lithic.",
  str_homestory_N19chuanshanjia_90010101_27_dialog_content = "Betulkah? Karena dia tampaknya cukup terkejut dengan gagasan tentang hewan yang berbicara, jika Anda bertanya kepada saya!",
  str_homestory_N19chuanshanjia_90010101_28_dialog_content = "K-Kami tahu banyak hewan yang bisa berbicara! Benar, Vice?",
  str_homestory_N19chuanshanjia_90010101_29_dialog_content = "Hah?",
  str_homestory_N19chuanshanjia_90010101_30_dialog_content = "(Kurasa Sahn tidak tahu kalau demi-human sudah tidak ada lagi...)",
  str_homestory_N19chuanshanjia_90010101_31_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_32_dialog_content = "Ah! B-Benar!",
  str_homestory_N19chuanshanjia_90010101_33_dialog_content = "Apakah Anda pikir saya lahir kemarin? Sangat jelas bahwa dia ragu-ragu sekarang!",
  str_homestory_N19chuanshanjia_90010101_34_dialog_content = "Er, ya, baiklah... Senang bertemu denganmu, Sahn. Nama saya adalah Vice, dan ini adalah PlayerName.",
  str_homestory_N19chuanshanjia_90010101_35_dialog_content = "Dia yang bertanggung jawab di sini, dan tidak akan pernah berbohong padamu.",
  str_homestory_N19chuanshanjia_90010101_36_dialog_content = "Hewan berbicara yang dia sebutkan adalah teman kita.",
  str_homestory_N19chuanshanjia_90010101_37_dialog_content = "Jika Anda masih tidak yakin, maka PlayerName hanya perlu membawa mereka untuk Anda lihat.",
  str_homestory_N19chuanshanjia_90010101_38_dialog_content = "Biarkan aku berpikir...",
  str_homestory_N19chuanshanjia_90010101_39_dialog_content = "(Tidakkah saya melihat <color=#FFB400>Korgon</color> dekat tepi hutan tadi? Saya hanya bisa membawanya ke sini!)",
  str_homestory_N19chuanshanjia_90010101_40_dialog_content = "Ah! Y-Ya! Harap tunggu di sini sebentar, Sahn!",
  str_homestory_N19chuanshanjia_90010101_41_dialog_content = "(Jangan katakan apapun tentang demi-human saat aku pergi, mengerti?)",
  str_homestory_N19chuanshanjia_90010101_42_dialog_content = "(T-Tentu saja! Cepat kembali, oke?)",
  str_homestory_N19chuanshanjia_90010111_1_dialog_content = "Mari kita temukan. Potong-potong!",
  str_homestory_N19chuanshanjia_90010102_1_dialog_content = "Hai! Korgon!",
  str_homestory_N19chuanshanjia_90010102_2_dialog_content = "Yo! Aku hanya mencarimu, bos!",
  str_homestory_N19chuanshanjia_90010102_3_dialog_content = "Berapa kali saya harus memberitahu Anda untuk berhenti memanggil saya \"bos\"?",
  str_homestory_N19chuanshanjia_90010102_4_dialog_content = "Ha! Bagus, bos! Bagaimanapun, Anda punya yang bagus <color=#FFB400>kayu</color> di tanganmu?",
  str_homestory_N19chuanshanjia_90010102_5_dialog_content = "Kayu?",
  str_homestory_N19chuanshanjia_90010102_6_dialog_content = "Mereka berpikir untuk membangun pelabuhan kecil di Pulau Sharkfang. Dengan begitu, mereka tidak perlu terus-menerus menyeret perahu ke pantai.",
  str_homestory_N19chuanshanjia_90010102_7_dialog_content = "Anda pasti sibuk. Tapi mari kita tunda bisnis kayu ini sebentar.",
  str_homestory_N19chuanshanjia_90010102_8_dialog_content = "Saya ingin memperkenalkan Anda kepada seseorang terlebih dahulu. Anda tidak perlu banyak bicara, dan cobalah untuk tidak menakutinya atau apa pun.",
  str_homestory_N19chuanshanjia_90010102_9_dialog_content = "Bertemu seseorang? Bukan masalah! Tapi kayu ini tidak akan mengumpulkan dirinya sendiri, bos... Mari kita lakukan ini besok, ya?",
  str_homestory_N19chuanshanjia_90010102_10_dialog_content = "Besok? Itu tidak akan berhasil, aku...",
  str_homestory_N19chuanshanjia_90010102_11_dialog_content = "Sigh... Baiklah, aku akan membantumu mengumpulkan kayu. Berapa banyak yang Anda butuhkan?",
  str_homestory_N19chuanshanjia_90010102_12_dialog_content = "<color=#FFB400>10</color> bagian dari mereka harus melakukannya. Aku akan membayarnya juga, jadi jangan khawatir!",
  str_homestory_N19chuanshanjia_90010102_13_dialog_content = "Segera!",
  str_homestory_N19chuanshanjia_90010112_1_dialog_content = "10 log sudah cukup.",
  str_homestory_N19chuanshanjia_90010103_1_dialog_content = "Apakah Anda mengumpulkan cukup kayu?",
  str_homestory_N19chuanshanjia_90010103_2_dialog_content = "Ini harus bekerja! ({1}/{2})",
  str_homestory_N19chuanshanjia_90010103_3_dialog_content = "Itu bos untukmu! Tidak bisa melakukannya sendiri dengan lebih baik!",
  str_homestory_N19chuanshanjia_90010103_4_dialog_content = "Sekarang ketika Anda bertemu dengannya, cobalah untuk tidak mengatakan sesuatu yang aneh. Hanya tersenyum dan mengangguk untuk sebagian besar dan kami akan baik-baik saja.",
  str_homestory_N19chuanshanjia_90010103_5_dialog_content = "Anda terus berbicara tentang orang ini, tetapi Anda masih belum memberi tahu saya siapa dia, bos! Dia bukan orang aneh, kan?",
  str_homestory_N19chuanshanjia_90010103_6_dialog_content = "Anda tahu saya belum berbicara dengan orang-orang seperti itu selama bertahun-tahun, bos ...",
  str_homestory_N19chuanshanjia_90010103_7_dialog_content = "Dia adalah binatang yang berbicara bahasa kita, jangan menakut-nakuti dia dan kita akan baik-baik saja.",
  str_homestory_N19chuanshanjia_90010103_8_dialog_content = "Yang saya katakan adalah, setiap kali Anda membuka mulut untuk berbicara, gigi setajam silet Anda bisa menjadi sedikit... tidak menyenangkan.",
  str_homestory_N19chuanshanjia_90010103_9_dialog_content = "Ya, ya, saya menangkap maksud Anda, bos.",
  str_homestory_N19chuanshanjia_90010103_10_dialog_content = "Belum.",
  str_homestory_N19chuanshanjia_90010104_1_dialog_content = "Saya kembali!",
  str_homestory_N19chuanshanjia_90010104_2_dialog_content = "Oh, syukurlah! Aku kehabisan hal untuk dibicarakan. Dia terus menanyakan segala macam pertanyaan... Aku hampir tidak bisa menahannya lagi.",
  str_homestory_N19chuanshanjia_90010104_3_dialog_content = "Lihat, Sahn!",
  str_homestory_N19chuanshanjia_90010104_4_dialog_content = "Salam pembuka!",
  str_homestory_N19chuanshanjia_90010104_5_dialog_content = "D-Dia akan memakanku hidup-hidup!!",
  str_homestory_N19chuanshanjia_90010104_6_dialog_content = "PlayerName... Mengapa Anda harus membawa orang itu, dari semua orang?!",
  str_homestory_N19chuanshanjia_90010104_7_dialog_content = "Apa maksudmu, \"pria itu\"?!",
  str_homestory_N19chuanshanjia_90010104_8_dialog_content = "Apakah kalian lupa bahwa saya seorang vegetarian? Satu-satunya hal yang saya lihat ketika saya melihat binatang kecil adalah sesuatu untuk dibelai dan diberi hadiah!",
  str_homestory_N19chuanshanjia_90010104_9_dialog_content = "Bukan salahku aku terlahir dengan mulut besar penuh gigi setajam silet!",
  str_homestory_N19chuanshanjia_90010104_10_dialog_content = "M-Maaf, teman. Aku terlalu cepat menilaimu dari penampilanmu...",
  str_homestory_N19chuanshanjia_90010104_11_dialog_content = "Senyummu mungkin menakutkan, harus kukatakan... Gigimu adalah beberapa yang paling terang dan paling putih yang pernah kulihat!",
  str_homestory_N19chuanshanjia_90010104_12_dialog_content = "B-Benarkah? Akhirnya, seseorang yang menghargai gigi saya!",
  str_homestory_N19chuanshanjia_90010104_13_dialog_content = "Gigi hiu saya sering ganti sendiri. Saya bisa menghancurkan gigi lama saya menjadi bubuk dan memberikannya kepada Anda untuk digunakan untuk memasak!",
  str_homestory_N19chuanshanjia_90010104_14_dialog_content = "I-Itu tidak perlu, terima kasih...",
  str_homestory_N19chuanshanjia_90010104_15_dialog_content = "Bagaimanapun, jangan ragu untuk datang mengunjungi Pulau Sharkfang kapan saja!",
  str_homestory_N19chuanshanjia_90010104_16_dialog_content = "Pemandangan terbaik di sana, terutama pada siang hari, saat matahari bersinar di atas ombak.",
  str_homestory_N19chuanshanjia_90010104_17_dialog_content = "Ah, tapi saya khawatir saya harus menolak undangan Anda yang ramah juga. Anda tahu, jenis kami... sangat tidak menyukai genangan air yang besar.",
  str_homestory_N19chuanshanjia_90010104_18_dialog_content = "Kami lebih betah di pegunungan. Jika Anda ingin mengunjungi kami di masa mendatang, Anda dapat menemukan kami di sini.",
  str_homestory_N19chuanshanjia_90010104_19_dialog_content = "Kami memutuskan untuk datang ke sini untuk berkunjung karena kami sudah terlalu lama terisolasi di pegunungan. Teman klan saya ingin melihat dunia luar.",
  str_homestory_N19chuanshanjia_90010104_20_dialog_content = "Saya hanya berharap tempat ini lebih damai daripada yang lain... Saya dan teman satu klan saya telah mengalami begitu banyak kesulitan...",
  str_homestory_N19chuanshanjia_90010104_21_dialog_content = "Jadi itu sebabnya kalian selalu kabur pada pandangan pertama dari spesies lain!",
  str_homestory_N19chuanshanjia_90010104_22_dialog_content = "Saya dapat meyakinkan Anda bahwa Cloud Gardens sangat aman.",
  str_homestory_N19chuanshanjia_90010104_23_dialog_content = "Lalu aku akan kembali ke klanku dan memberitahu mereka tentang tempat ini sekaligus!",
  str_homestory_N19chuanshanjia_90010104_24_dialog_content = "T-Tunggu! Saya tidak bisa menyentuh timbangan Anda!",
  str_homestory_N19chuanshanjia_90010104_25_dialog_content = "Saya yakin Anda akan memiliki kesempatan lain suatu hari nanti, Korgon.",
  str_homestory_N19chuanshanjia_90010104_26_dialog_content = "Tapi pertama-tama, kau harus menyingkirkan senyummu itu...",
  str_homestory_N19chuanshanjia_90010104_27_dialog_content = "... Ini benar-benar bukan salahku, kau tahu.",
  str_homestory_N19chuanshanjia_90010201_1_dialog_content = "Hmm? Kamu bukan Sahn, kan?",
  str_homestory_N19chuanshanjia_90010201_2_dialog_content = "Eep! aku <color=#FFB400>Jiji</color>, pemakai ikat kepala paling kuat dan paling nyaman di seluruh negeri!",
  str_homestory_N19chuanshanjia_90010201_3_dialog_content = "Sahn memberi tahu kami tentang cara Anda yang damai dan bersahabat, jadi saya segera datang!",
  str_homestory_N19chuanshanjia_90010201_4_dialog_content = "Katakan padaku, apa pendapatmu tentang ikat kepalaku? Eep!",
  str_homestory_N19chuanshanjia_90010201_5_option_content = "Ini bagus.",
  str_homestory_N19chuanshanjia_90010201_6_dialog_content = "Apa tanggapan yang suam-suam kuku ...",
  str_homestory_N19chuanshanjia_90010201_7_option_content = "Ini fantastis!",
  str_homestory_N19chuanshanjia_90010201_8_dialog_content = "Ini sangat feminin.",
  str_homestory_N19chuanshanjia_90010201_9_dialog_content = "Itu milik saya yang paling berharga! Lihat saja kerajinan ini! kualitas ini!",
  str_homestory_N19chuanshanjia_90010201_10_dialog_content = "A-Ngomong-ngomong... Sekarang setelah kamu di sini, ada yang bisa saya bantu?",
  str_homestory_N19chuanshanjia_90010201_11_dialog_content = "Eep! Ya, sebenarnya! Saya baru saja membuat lelucon baru, dan saya datang untuk membagikannya kepada Anda!",
  str_homestory_N19chuanshanjia_90010201_12_dialog_content = "Lagi pula, saya cukup jenius komedi di antara Pangalo!",
  str_homestory_N19chuanshanjia_90010201_13_dialog_content = "Impian saya adalah menjadi komedian terhebat di dunia, sehingga saya dapat menyebarkan kegembiraan yang tak terkendali dan tawa yang memilukan kepada semua orang!",
  str_homestory_N19chuanshanjia_90010201_14_dialog_content = "Lelucon? Oke, mari kita dengarkan!",
  str_homestory_N19chuanshanjia_90010201_15_dialog_content = "Baiklah kalau begitu! Buka telinga Anda, bersiaplah untuk itu! Eep!",
  str_homestory_N19chuanshanjia_90010201_16_dialog_content = "Dahulu kala, ada seorang pejuang pemberani.",
  str_homestory_N19chuanshanjia_90010201_17_dialog_content = "Pedangnya dingin, tangannya dingin, hatinya dingin, kepribadiannya dingin seperti mentimun... Faktanya, seluruh keberadaannya sedingin es.",
  str_homestory_N19chuanshanjia_90010201_18_dialog_content = "Dan pada akhirnya, dia mati kedinginan.",
  str_homestory_N19chuanshanjia_90010201_19_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_20_dialog_content = "<size=65>Hahahahaha!</size>",
  str_homestory_N19chuanshanjia_90010201_21_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_22_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_23_dialog_content = "<size=65>Ahahaha.</size>",
  str_homestory_N19chuanshanjia_90010201_24_dialog_content = "Eep! Wajahmu tidak menipuku! Itu adalah tawa paling dipaksakan yang pernah saya dengar dalam hidup saya!",
  str_homestory_N19chuanshanjia_90010201_25_dialog_content = "Er... I-Itu karena selera humorku benar-benar aneh! Mengapa Anda tidak mencoba menceritakan lelucon Anda kepada orang lain?",
  str_homestory_N19chuanshanjia_90010201_26_dialog_content = "K-Kamu sebaiknya tidak berbohong padaku!",
  str_homestory_N19chuanshanjia_90010201_27_dialog_content = "Aku tidak, jujur! Saya pikir saya ingat melihat Revy di sekitar sini di suatu tempat... Sempurna!",
  str_homestory_N19chuanshanjia_90010202_1_dialog_content = "Hai, Revy? Anda terlihat seperti melamun.",
  str_homestory_N19chuanshanjia_90010202_2_dialog_content = "Saya menghitung bilah rumput di tanah.",
  str_homestory_N19chuanshanjia_90010202_3_dialog_content = "Begitu ya... Lagi pula, saya punya seseorang di sini yang ingin menceritakan lelucon, dan saya pikir Anda akan sangat menikmatinya. Tertarik?",
  str_homestory_N19chuanshanjia_90010202_4_dialog_content = "Tentu.",
  str_homestory_N19chuanshanjia_90010202_5_dialog_content = "Eep! Luar biasa! Dia terlihat seperti seseorang yang bisa menghargai sedikit humor kering!",
  str_homestory_N19chuanshanjia_90010202_6_dialog_content = "Aku mendengarkan.",
  str_homestory_N19chuanshanjia_90010202_7_dialog_content = "Dahulu kala, ada seorang pejuang pemberani.",
  str_homestory_N19chuanshanjia_90010202_8_dialog_content = "Pedangnya dingin, tangannya dingin, hatinya dingin, kepribadiannya dingin seperti mentimun... Faktanya, seluruh keberadaannya sedingin es.",
  str_homestory_N19chuanshanjia_90010202_9_dialog_content = "Dan pada akhirnya, dia mati kedinginan.",
  str_homestory_N19chuanshanjia_90010202_10_dialog_content = "Oh.",
  str_homestory_N19chuanshanjia_90010202_11_dialog_content = "Eep! A-Apakah hanya itu yang kamu katakan?!",
  str_homestory_N19chuanshanjia_90010202_12_dialog_content = "(Sial! Sepertinya tidak genap Revy akan menertawakan lelucon seperti itu ...)",
  str_homestory_N19chuanshanjia_90010202_13_dialog_content = "M-Maaf, Jiji! Biarkan aku pergi mencari orang lain! Lagipula, Revy sedang sibuk dengan sesuatu yang sangat penting barusan.",
  str_homestory_N19chuanshanjia_90010202_14_dialog_content = "Bukankah itu benar, Revy?",
  str_homestory_N19chuanshanjia_90010202_15_dialog_content = "Hah?",
  str_homestory_N19chuanshanjia_90010202_16_dialog_content = "Ayo pergi! Jangan kemana-mana, Jiji! Saya akan menemukan audiens yang sempurna untuk lelucon Anda, saya janji!",
  str_homestory_N19chuanshanjia_90010203_1_dialog_content = "Anda satu-satunya di sini?",
  str_homestory_N19chuanshanjia_90010203_2_dialog_content = "Maksudnya apa?",
  str_homestory_N19chuanshanjia_90010203_3_dialog_content = "Kamu hanya... Kelihatannya bukan tipe orang yang suka bercanda, itu saja.",
  str_homestory_N19chuanshanjia_90010203_4_dialog_content = "Sesuatu tentang pedang yang dingin dan hati yang dingin...",
  str_homestory_N19chuanshanjia_90010203_5_dialog_content = "Sebuah \"pisau dingin\"? Apa yang kau bicarakan?",
  str_homestory_N19chuanshanjia_90010203_6_dialog_content = "Hmm? Dayna!",
  str_homestory_N19chuanshanjia_90010203_7_dialog_content = "Ha ha ha! Apakah kamu serius?!",
  str_homestory_N19chuanshanjia_90010203_8_dialog_content = "Apakah kamu tertawa?",
  str_homestory_N19chuanshanjia_90010203_9_dialog_content = "Apakah itu leluconmu, Boatscrapper?",
  str_homestory_N19chuanshanjia_90010203_10_dialog_content = "T-Tidak, itu sama sekali bukan leluconku. Orang lain datang dengan itu.",
  str_homestory_N19chuanshanjia_90010203_11_dialog_content = "Nah, bawa aku ke mereka! Aku kebetulan bebas sekarang.",
  str_homestory_N19chuanshanjia_90010211_1_dialog_content = "Lakukan itu, pembuat kapal!",
  str_homestory_N19chuanshanjia_90010204_1_dialog_content = "Dia? Tapi dia tidak terlihat seperti tipe orang yang mengerti lelucon...",
  str_homestory_N19chuanshanjia_90010204_2_dialog_content = "Apakah kamu bercanda? Saya mendengar semua jenis lelucon di Umbraton!",
  str_homestory_N19chuanshanjia_90010204_3_dialog_content = "Eep! Kemudian mari kita mencobanya. Dengarkan baik-baik, sekarang!",
  str_homestory_N19chuanshanjia_90010204_4_dialog_content = "Dahulu kala, ada seorang pejuang pemberani. Pedangnya dingin...",
  str_homestory_N19chuanshanjia_90010204_5_dialog_content = "Aku mengerti.",
  str_homestory_N19chuanshanjia_90010204_6_dialog_content = "Anda tampaknya tidak terlalu antusias.",
  str_homestory_N19chuanshanjia_90010204_7_dialog_content = "Jangan menyerah, Ji! Terus berlanjut!",
  str_homestory_N19chuanshanjia_90010204_8_dialog_content = "Tangannya dingin...",
  str_homestory_N19chuanshanjia_90010204_9_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10_dialog_content = "Hatinya dingin.",
  str_homestory_N19chuanshanjia_90010204_10X1_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10X2_dialog_content = "Faktanya, seluruh tubuhnya sedingin es.",
  str_homestory_N19chuanshanjia_90010204_10X3_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_11_dialog_content = "... Pffff.",
  str_homestory_N19chuanshanjia_90010204_12_dialog_content = "Dan pada akhirnya, dia mati kedinginan.",
  str_homestory_N19chuanshanjia_90010204_13_dialog_content = "<size=65>Hahahahaha! Lelucon itu benar-benar kering!</size>",
  str_homestory_N19chuanshanjia_90010204_14_dialog_content = "<size=65>Apa?!?</size>",
  str_homestory_N19chuanshanjia_90010204_15_dialog_content = "Pengiriman Anda bisa membutuhkan beberapa pekerjaan, tetapi leluconnya sangat kuat! Aku butuh tertawa!",
  str_homestory_N19chuanshanjia_90010204_16_dialog_content = "Saya senang seseorang akhirnya menemukan humor di dalamnya!",
  str_homestory_N19chuanshanjia_90010204_17_dialog_content = "Dengan lelucon seperti itu, Anda bisa membuat beberapa penggemar jatuh di Umbraton!",
  str_homestory_N19chuanshanjia_90010204_18_dialog_content = "Anda bahkan mungkin akan menjadi terkenal.",
  str_homestory_N19chuanshanjia_90010204_19_dialog_content = "Eep!!! B-Benarkah? Aku harus pergi memberitahu teman klanku!",
  str_homestory_N19chuanshanjia_90010204_20_dialog_content = "Hahahahaha! Lelucon itu sangat kering! Dan sangat lucu!",
  str_homestory_N19chuanshanjia_90010204_21_dialog_content = "aku harus bertanya PlayerName untuk menceritakannya lagi ketika saya mendapat kesempatan.",
  str_homestory_N19chuanshanjia_90010301_1_dialog_content = "<size=65>Gwa! Akhirnya aku menemukanmu!</size>",
  str_homestory_N19chuanshanjia_90010301_2_dialog_content = "Pangalo lain, ya? Dan yang ini sepertinya tidak terlalu senang... Apakah kamu teman Sahn dan Jiji, kebetulan?",
  str_homestory_N19chuanshanjia_90010301_3_dialog_content = "Gwa! Kamu harus PlayerName! saya <color=#FFB400>Gendut</color>, dan aku datang untuk membalas dendam!",
  str_homestory_N19chuanshanjia_90010301_4_dialog_content = "Karenamu, Jiji menggulingkanku dan menendangku seperti bola!",
  str_homestory_N19chuanshanjia_90010301_5_dialog_content = "T-Tunggu, kalau begitu bukankah seharusnya kamu membalas dendam pada Jiji, bukan aku?",
  str_homestory_N19chuanshanjia_90010301_6_dialog_content = "Gwa! Dia bilang dia melakukannya hanya karena kamu berbohong padanya!",
  str_homestory_N19chuanshanjia_90010301_7_dialog_content = "Jiji datang berlari ke arahku, mengatakan sesuatu tentang \"pisau dingin\" dan \"tangan dingin\"...",
  str_homestory_N19chuanshanjia_90010301_8_dialog_content = "\"Dan kemudian dia membeku sampai mati.\"",
  str_homestory_N19chuanshanjia_90010301_9_dialog_content = "Gwa! Tepat! Sungguh lelucon yang tidak lucu.",
  str_homestory_N19chuanshanjia_90010301_10_dialog_content = "Tapi dia terus bersikeras bahwa itu adalah lelucon paling lucu di dunia, dan bahwa Anda telah membuktikannya!",
  str_homestory_N19chuanshanjia_90010301_11_dialog_content = "Dia sangat marah ketika dia mengetahui bahwa itu sebenarnya lelucon yang buruk, dan bahwa Anda berbohong kepadanya tentang hal itu!",
  str_homestory_N19chuanshanjia_90010301_12_dialog_content = "Dan kemudian dia mengubahku menjadi bola tendangan.",
  str_homestory_N19chuanshanjia_90010301_13_dialog_content = "Dia menendangku begitu lama, dunia masih berputar di depan mataku.",
  str_homestory_N19chuanshanjia_90010301_14_dialog_content = "Jadi saya berpikir, jika Anda yang memulai semua ini... Maka Anda yang harus dihukum, bukan saya!",
  str_homestory_N19chuanshanjia_90010301_15_dialog_content = "P-Hukuman?",
  str_homestory_N19chuanshanjia_90010301_16_dialog_content = "Gwa! Betul sekali! Anda harus meringkuk menjadi bola dan biarkan dia menendang Anda!",
  str_homestory_N19chuanshanjia_90010301_17_dialog_content = "A-Logika macam apa itu...?",
  str_homestory_N19chuanshanjia_90010301_18_dialog_content = "Nah, apakah Anda punya ide yang lebih baik?",
  str_homestory_N19chuanshanjia_90010301_19_dialog_content = "Kalau saja Anda jujur dengan Jiji tentang leluconnya sejak awal, semua ini tidak akan terjadi.",
  str_homestory_N19chuanshanjia_90010301_20_dialog_content = "T-Tapi setiap orang punya selera humornya masing-masing...",
  str_homestory_N19chuanshanjia_90010301_21_dialog_content = "Saya pikir memberi Jiji dorongan itu penting!",
  str_homestory_N19chuanshanjia_90010301_22_dialog_content = "Itu mungkin tidak selucu yang dia harapkan, tapi terkadang sedikit, kebohongan putih... Maksudku, itu masih cukup lucu! Dan Jiji membutuhkan dukungan kita!",
  str_homestory_N19chuanshanjia_90010301_23_dialog_content = "Jiji? Gwaaa! Bagaimana dengan saya?! Lihat saja bentuk saya!",
  str_homestory_N19chuanshanjia_90010301_24_dialog_content = "Saya sudah meringkuk begitu lama sehingga saya tidak bisa meluruskan punggung saya lagi!",
  str_homestory_N19chuanshanjia_90010301_25_dialog_content = "Yang saya butuhkan, adalah beberapa makanan!",
  str_homestory_N19chuanshanjia_90010301_26_dialog_content = "\"Makanan\"...? Maksudmu makanan?",
  str_homestory_N19chuanshanjia_90010301_27_dialog_content = "Benar! Sesuatu <color=#FFB400>manis</color> akan bekerja paling baik, saya pikir.",
  str_homestory_N19chuanshanjia_90010301_28_dialog_content = "Makanan penutup, ya? Saya pikir saya melihat <color=#FFB400>Pedagang Chubb</color> menuju hutan... Mari kita periksa.",
  str_homestory_N19chuanshanjia_90010311_1_dialog_content = "Anda akan menemukan sesuatu yang manis, bukan?",
  str_homestory_N19chuanshanjia_90010302_1_dialog_content = "Makanan penutup? Segalanya. Chubb.",
  str_homestory_N19chuanshanjia_90010302_2_dialog_content = "Segalanya?",
  str_homestory_N19chuanshanjia_90010302_3_dialog_content = "Ini bukan toko serba ada untuk semua kebutuhan camilan Anda! Anda harus memesan terlebih dahulu! Chubb!",
  str_homestory_N19chuanshanjia_90010302_4_dialog_content = "Memesan...?",
  str_homestory_N19chuanshanjia_90010302_5_dialog_content = "Chubb! Betul sekali! Melihat? <color=#FFB400>Vice</color> memiliki pesanan kue di sini!",
  str_homestory_N19chuanshanjia_90010302_6_dialog_content = "Vice! Tentu saja! Apakah Anda tahu di mana dia?",
  str_homestory_N19chuanshanjia_90010302_7_dialog_content = "Di tepi sungai. Chubb!",
  str_homestory_N19chuanshanjia_90010302_8_dialog_content = "Terima kasih! Chubb!",
  str_homestory_N19chuanshanjia_90010302_9_dialog_content = "Jangan menyebutkannya! Chubb!",
  str_homestory_N19chuanshanjia_90010302_10_dialog_content = "Hah?",
  str_homestory_N19chuanshanjia_90010312_1_dialog_content = "Di tepi sungai. Vice, Chubb.",
  str_homestory_N19chuanshanjia_90010303_1_dialog_content = "Hai, Vice? Apa itu di wajahmu...?",
  str_homestory_N19chuanshanjia_90010303_2_dialog_content = "Hah?",
  str_homestory_N19chuanshanjia_90010303_3_dialog_content = "Anda tidak makan kue sekarang, kan?",
  str_homestory_N19chuanshanjia_90010303_4_dialog_content = "Bagaimana kamu tahu?",
  str_homestory_N19chuanshanjia_90010303_5_dialog_content = "Argh, aku terlambat!",
  str_homestory_N19chuanshanjia_90010303_6_dialog_content = "Bersalah seperti yang dituduhkan, hehe... Apakah Anda sangat menginginkan kue?",
  str_homestory_N19chuanshanjia_90010303_7_dialog_content = "Ceritanya panjang... Aku hanya butuh kue sekarang, meski hanya sepotong kecil.",
  str_homestory_N19chuanshanjia_90010303_8_dialog_content = "Ketika saya pergi untuk mengambil kue saya, saya melihat <color=#FFB400>Korgon</color> menempatkan pesanan untuk beberapa, juga. Saya tidak tahu untuk apa, meskipun ...",
  str_homestory_N19chuanshanjia_90010303_9_dialog_content = "Tapi aku melihatnya berjalan ke <color=#FFB400>Lapangan Eceng Gondok</color> kemudian.",
  str_homestory_N19chuanshanjia_90010303_10_dialog_content = "Lapangan Hyacinth, ya? Mengerti!",
  str_homestory_N19chuanshanjia_90010313_1_dialog_content = "Cepat sekarang! Atau dia akan selesai memakannya!",
  str_homestory_N19chuanshanjia_90010304_1_dialog_content = "Hai! Akhirnya aku menemukanmu!",
  str_homestory_N19chuanshanjia_90010304_2_dialog_content = "Apa kabar, bos?",
  str_homestory_N19chuanshanjia_90010304_3_dialog_content = "Masih ada sisa kue?",
  str_homestory_N19chuanshanjia_90010304_4_dialog_content = "Oh? Saya tidak tahu Anda memiliki gigi manis, bos?",
  str_homestory_N19chuanshanjia_90010304_5_dialog_content = "Ah! Ya saya lakukan.",
  str_homestory_N19chuanshanjia_90010304_6_dialog_content = "Hah? Nah, itu tidak mungkin benar. Saya ingat Anda mengatakan kepada saya bahwa Anda tidak peduli dengan permen.",
  str_homestory_N19chuanshanjia_90010304_7_dialog_content = "Kau benar, tapi... Ceritanya agak panjang.",
  str_homestory_N19chuanshanjia_90010304_8_dialog_content = "Jangan ngambek, bos! Saya benar-benar mengerti! Setiap orang punya rahasianya masing-masing...",
  str_homestory_N19chuanshanjia_90010304_9_dialog_content = "Dan jika firasat saya benar... Saya akan mengatakan Anda memiliki makhluk kecil untuk diberi makan, bukan?",
  str_homestory_N19chuanshanjia_90010304_10_dialog_content = "H-Hah? Eh, maksudku... Yeah, yeah, aku...",
  str_homestory_N19chuanshanjia_90010304_11_dialog_content = "Lagi pula, apakah Anda pikir Anda bisa menyisihkan sedikit kue...?",
  str_homestory_N19chuanshanjia_90010304_12_dialog_content = "Tidak masalah!",
  str_homestory_N19chuanshanjia_90010314_1_dialog_content = "Memang tidak banyak, tapi seharusnya cukup. Apa yang Anda katakan, bos?",
  str_homestory_N19chuanshanjia_90010305_1_dialog_content = "Saya kembali! Dan saya membawa kue!",
  str_homestory_N19chuanshanjia_90010305_2_dialog_content = "Tunggu!",
  str_homestory_N19chuanshanjia_90010305_3_dialog_content = "Ada apa?",
  str_homestory_N19chuanshanjia_90010305_4_dialog_content = "Kue ini belum benar <color=#FFB400>berpengalaman</color>, memilikinya?",
  str_homestory_N19chuanshanjia_90010305_5_dialog_content = "\"Berpengalaman\"...?",
  str_homestory_N19chuanshanjia_90010305_6_dialog_content = "Sementara rasa manis kue sering kali menjadi rasa utama, ada bumbu lain yang sama pentingnya!",
  str_homestory_N19chuanshanjia_90010305_7_dialog_content = "Apa jenis bumbu yang Anda bicarakan? Saya rasa tidak akan mudah untuk menemukan bahan yang sudah jadi di sini...",
  str_homestory_N19chuanshanjia_90010305_8_dialog_content = "Tidak perlu, kami punya banyak di sini!",
  str_homestory_N19chuanshanjia_90010305_9_dialog_content = "Disini dimana?",
  str_homestory_N19chuanshanjia_90010305_10_dialog_content = "Tanah di bawah kita, tentu saja.",
  str_homestory_N19chuanshanjia_90010305_11_dialog_content = "S-Tanah...?!",
  str_homestory_N19chuanshanjia_90010305_12_dialog_content = "Jenis kami menggali melalui pegunungan hari demi hari, dan sering berakhir dengan memakan tanah dalam prosesnya.",
  str_homestory_N19chuanshanjia_90010305_13_dialog_content = "Dan, tentu saja, berbagai jenis tanah memiliki rasa yang berbeda. Secara pribadi, saya suka menambahkan satu sendok tanah berumput ke makanan saya untuk rasa yang sedikit astringen. Itu yang terbaik!",
  str_homestory_N19chuanshanjia_90010305_14_dialog_content = "Ah, hanya berpikir untuk menambahkan beberapa ke kue itu... Mulutku sudah mulai berair!",
  str_homestory_N19chuanshanjia_90010305_15_dialog_content = "Dunia terkadang bisa menjadi tempat yang sangat aneh...",
  str_homestory_N19chuanshanjia_90010305_16_dialog_content = "Bagaimanapun, Anda berterima kasih! Sekarang, saya akan pergi mencari tanah yang cocok untuk kue ini, jadi saya bisa membaginya dengan Jiji sebagai persembahan perdamaian!",
  str_homestory_N19chuanshanjia_90010305_17_dialog_content = "Mungkin kemudian, saya bisa meyakinkan dia untuk menghindarkan saya dari hukuman lebih lanjut! Gwa!",
  str_homestory_N19chuanshanjia_90010305_18_dialog_content = "Benar-benar selera yang berbeda... Meskipun kurasa ada kue untuk semua orang di luar sana, ya?",
  str_homestory_N19chuanshanjia_90010401_1_dialog_content = "Saya mendengar Anda mengalahkan Tubby! Kalahkan dia dengan baik, aku dengar!",
  str_homestory_N19chuanshanjia_90010401_2_dialog_content = "Kalian benar-benar memiliki bakat untuk salah paham dengan orang lain...?",
  str_homestory_N19chuanshanjia_90010401_3_dialog_content = "Za! Tubby menyerbu beberapa hari yang lalu, mengatakan dia akan menyelesaikan skor dengan Anda! Selesaikan skor!",
  str_homestory_N19chuanshanjia_90010401_4_dialog_content = "Tapi kemudian dia kembali dengan bahagia dan riang! Katanya dia tidak melakukan apa-apa! Tidak ada satu hal pun!",
  str_homestory_N19chuanshanjia_90010401_5_dialog_content = "Anda pasti telah mengalahkannya dengan bodoh! Kalahkan otaknya, bukan?!",
  str_homestory_N19chuanshanjia_90010401_6_dialog_content = "Aku tidak melakukan hal seperti itu! Saya baru saja berbagi sepotong kue dengan Tubby, itu saja!",
  str_homestory_N19chuanshanjia_90010401_7_dialog_content = "Za! Anda harus cukup pejuang! Seorang prajurit yang terampil, memang!",
  str_homestory_N19chuanshanjia_90010401_8_dialog_content = "aku <color=#FFB400>Cerewet</color>. Sebagai pejuang Lithic Pangalos, dengan ini saya menantang Anda untuk bertempur! Untuk bertempur!",
  str_homestory_N19chuanshanjia_90010401_9_dialog_content = "Kalian tidak terlalu mendengarkan apa yang orang lain katakan, kan...?",
  str_homestory_N19chuanshanjia_90010401_10_dialog_content = "Maaf mengecewakanmu, Repot, tapi aku sama sekali bukan petarung. Anda harus bertarung dengan orang lain.",
  str_homestory_N19chuanshanjia_90010401_11_dialog_content = "Za? Anda tidak ingin melawan saya?",
  str_homestory_N19chuanshanjia_90010401_12_dialog_content = "Mungkinkah... Bahwa Anda begitu kuat, Anda tidak dapat menahan kekuatan besar Anda? Bahwa Anda takut melakukan pertempuran dengan saya akan mengakibatkan kematian saya yang mengerikan?",
  str_homestory_N19chuanshanjia_90010401_13_dialog_content = "Jika demikian... maka kirim murid terkuatmu ke dalam pertempuran! Murid terbaikmu!! Za!!!",
  str_homestory_N19chuanshanjia_90010401_14_dialog_content = "D-Murid...?",
  str_homestory_N19chuanshanjia_90010401_15_dialog_content = "Ya! Jika Anda tidak akan melawan saya karena takut menyakiti saya, maka biarkan murid Anda bertarung menggantikan Anda! Za!",
  str_homestory_N19chuanshanjia_90010401_16_dialog_content = "Kalian BENAR-BENAR tidak mendengarkan apa yang orang lain katakan, sama sekali!",
  str_homestory_N19chuanshanjia_90010401_17_dialog_content = "Omong kosong! Aku mendengarmu dengan keras dan jelas. Sekarang kirimkan murid terkuatmu! Aku akan menunggu di sini dengan penuh harap akan pertempuran kita yang akan datang!",
  str_homestory_N19chuanshanjia_90010401_18_dialog_content = "Oke.",
  str_homestory_N19chuanshanjia_90010401_19_dialog_content = "Sepertinya saya memiliki kesalahpahaman lain di tangan saya ... Kurasa aku harus pergi mencari seseorang untuk menangani ini.",
  str_homestory_N19chuanshanjia_90010401_20_dialog_content = "Za! Apa yang kau gumamkan? Ceritakan sekarang!",
  str_homestory_N19chuanshanjia_90010401_21_dialog_content = "Aku bilang aku akan jalan-jalan di tepi sungai. Aku akan kembali sebentar lagi.",
  str_homestory_N19chuanshanjia_90010402_1_dialog_content = "Apa yang kamu lihat? Chubb.",
  str_homestory_N19chuanshanjia_90010402_2_dialog_content = "Sigh... Kau terlihat seperti petarung sepertiku...",
  str_homestory_N19chuanshanjia_90010402_3_dialog_content = "Kami Chubbs tidak cocok untuk bertarung, tidak. Chubb.",
  str_homestory_N19chuanshanjia_90010402_4_dialog_content = "Bagaimanapun, ini adalah tempat yang damai. Chubb.",
  str_homestory_N19chuanshanjia_90010402_5_dialog_content = "Hei ... Apakah itu? Barton? Apa yang dia lakukan di sini? Chubb!",
  str_homestory_N19chuanshanjia_90010402_6_dialog_content = "Dia mensurvei medan untuk tempat membangun kamp pelatihan untuk rekrutan baru. Chubb!",
  str_homestory_N19chuanshanjia_90010402_7_dialog_content = "Ini benar-benar dia!",
  str_homestory_N19chuanshanjia_90010402_8_dialog_content = "Ch-Chubb?",
  str_homestory_N19chuanshanjia_90010411_1_dialog_content = "Di dekat sini. Barton, Chubb.",
  str_homestory_N19chuanshanjia_90010403_1_dialog_content = "Kita bisa mengemas bumi di sini untuk tempat latihan dan meletakkan fondasi untuk barak di sana...",
  str_homestory_N19chuanshanjia_90010403_2_dialog_content = "Anda disana, Barton!",
  str_homestory_N19chuanshanjia_90010403_3_dialog_content = "Ah, waktu Anda tidak bisa lebih baik! Saya butuh bantuan Anda dengan sesuatu, dan saya harus menyita tanah ini untuk melakukannya!",
  str_homestory_N19chuanshanjia_90010403_4_dialog_content = "C-Komandan..?",
  str_homestory_N19chuanshanjia_90010403_5_dialog_content = "Ini terlalu damai di sini, yang tidak akan berhasil!",
  str_homestory_N19chuanshanjia_90010403_6_dialog_content = "Kalian semua seperti domba yang duduk di sarang serigala!",
  str_homestory_N19chuanshanjia_90010403_7_dialog_content = "Anda membutuhkan penjaga! Anda membutuhkan tentara!",
  str_homestory_N19chuanshanjia_90010403_8_dialog_content = "Jadi tentu saja, Anda membutuhkan kamp pelatihan terlebih dahulu dan terutama.",
  str_homestory_N19chuanshanjia_90010403_9_dialog_content = "Serahkan padaku! Saya akan mendirikan resimen ini, dan saya akan melatih mereka juga!",
  str_homestory_N19chuanshanjia_90010403_10_dialog_content = "Dan percayalah, saya tidak akan beristirahat sampai pekerjaan selesai! Dengan begitu, jumlah legiunku sendiri bisa meningkat, juga...",
  str_homestory_N19chuanshanjia_90010403_11_dialog_content = "Saya cukup yakin itulah satu-satunya alasan Anda melakukan ini ...",
  str_homestory_N19chuanshanjia_90010403_12_dialog_content = "Sudahlah, sekarang bukan waktunya untuk menanyakan hal itu.",
  str_homestory_N19chuanshanjia_90010403_13_dialog_content = "Apakah Anda pikir kamp Anda bisa menunggu sedikit lebih lama, Barton? Saya memiliki seseorang di sini yang ingin menguji keberanian mereka melawan Anda.",
  str_homestory_N19chuanshanjia_90010403_14_dialog_content = "Seorang rekrutan baru telah datang mengetuk, eh?",
  str_homestory_N19chuanshanjia_90010403_15_dialog_content = "Dimana mereka?",
  str_homestory_N19chuanshanjia_90010403_16_dialog_content = "Tepat di sana.",
  str_homestory_N19chuanshanjia_90010403_17_dialog_content = "Baiklah, waktunya untuk pelajaran kerendahan hati! Mungkin mereka akan berpikir dua kali untuk menantang instruktur di hari pertama mereka...",
  str_homestory_N19chuanshanjia_90010403_18_dialog_content = "T-Tunggu, Barton! Saya masih memiliki lebih banyak untuk memberitahu Anda!",
  str_homestory_N19chuanshanjia_90010412_1_dialog_content = "Kenapa kamu masih disini?",
  str_homestory_N19chuanshanjia_90010404_1_dialog_content = "Jadi kau pemula kecil yang mencoba membuat masalah bagi kami, kan?",
  str_homestory_N19chuanshanjia_90010404_2_dialog_content = "Za! Kamu bahkan lebih sombong dari PlayerName! Jauh lebih sombong!",
  str_homestory_N19chuanshanjia_90010404_3_dialog_content = "Saya kira Anda juga seorang petarung yang terampil, ya? Za!",
  str_homestory_N19chuanshanjia_90010404_4_dialog_content = "Mereka sudah gatal untuk bertarung! Saya praktis bisa melihat bunga api beterbangan...",
  str_homestory_N19chuanshanjia_90010404_5_dialog_content = "Saya tidak perlu menjadi pejuang yang terampil untuk menempatkan rekrutan yang tidak patuh di tempat mereka!",
  str_homestory_N19chuanshanjia_90010404_6_dialog_content = "Anda tidak terlihat seperti seorang pejuang. Tapi ada banyak orang aneh sepertimu di Cloud Gardens.",
  str_homestory_N19chuanshanjia_90010404_7_dialog_content = "Persetan dengan itu! Jika lengan dan kakimu berfungsi dengan baik, dan ekormu itu bukan hanya untuk pertunjukan, maka aku akan menjadikanmu prajurit!",
  str_homestory_N19chuanshanjia_90010404_8_dialog_content = "Sekarang, biarkan pelatihan dimulai!",
  str_homestory_N19chuanshanjia_90010404_9_dialog_content = "Seperti yang diharapkan dari murid master sejati! Kerasnya kata-kata Anda sama kuatnya dengan kepercayaan diri yang Anda pancarkan!",
  str_homestory_N19chuanshanjia_90010404_10_dialog_content = "Tetapi meskipun demikian, Anda meremehkan saya dengan risiko Anda sendiri! Waktunya telah tiba untuk memutuskan siapa di antara kita yang lebih kuat! Zaaaa!",
  str_homestory_N19chuanshanjia_90010404_11_dialog_content = "<size=65>Tunggu!</size>",
  str_homestory_N19chuanshanjia_90010404_12_dialog_content = "Saya tidak berpikir pertempuran adalah cara yang tepat untuk melakukan ini! Kenapa kalian berdua tidak...",
  str_homestory_N19chuanshanjia_90010404_13_dialog_content = "Adakan kontes \"<color=#FFB400>aura</color>,\" alih-alih?",
  str_homestory_N19chuanshanjia_90010404_14_dialog_content = "... Za? \"Aura\"?",
  str_homestory_N19chuanshanjia_90010404_15_dialog_content = "aura kita?",
  str_homestory_N19chuanshanjia_90010404_16_dialog_content = "Ini seperti... Kombinasi keinginan Anda untuk bertarung, kondisi fisik Anda, dan kemampuan tempur Anda, serta hal-hal lain.",
  str_homestory_N19chuanshanjia_90010404_17_dialog_content = "Aku seorang Caelestit, ingat? Saya dapat menggunakan kekuatan saya untuk melihat aura Anda dan menentukan siapa di antara Anda yang lebih kuat.",
  str_homestory_N19chuanshanjia_90010404_18_dialog_content = "A-Apakah itu mungkin?!",
  str_homestory_N19chuanshanjia_90010404_19_dialog_content = "Itu... Aku bisa membuktikan kekuatan kekuatan psikis Caelestites. Metode ini harus bekerja sebaik pertempuran yang sebenarnya.",
  str_homestory_N19chuanshanjia_90010404_20_dialog_content = "Mari kita mulai.",
  str_homestory_N19chuanshanjia_90010404_21_dialog_content = "<anim type=Shake><size=65>Grrrr—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_22_dialog_content = "<anim type=Shake><size=65>Zaa—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_23_dialog_content = "A-Apa ini?! Saya tidak bisa membedakan mana yang lebih kuat!",
  str_homestory_N19chuanshanjia_90010404_24_dialog_content = "Mereka berdua sangat kuat!!",
  str_homestory_N19chuanshanjia_90010404_25_dialog_content = "Saya mengerti!",
  str_homestory_N19chuanshanjia_90010404_26_dialog_content = "Menakjubkan!",
  str_homestory_N19chuanshanjia_90010404_27_dialog_content = "Itu tampak seperti hasil imbang bagi saya, teman-teman.",
  str_homestory_N19chuanshanjia_90010404_28_dialog_content = "(Pangalo lain, kebohongan lain ...)",
  str_homestory_N19chuanshanjia_90010404_29_dialog_content = "Saya harus berkata, PlayerName, Anda berhasil menemukan rekrutan baru yang menjanjikan! Anda memiliki terima kasih saya!",
  str_homestory_N19chuanshanjia_90010404_30_dialog_content = "Illumina bisa menggunakan orang sepertimu, dan kau tidak akan pernah menginginkan apapun di bawah kepemimpinanku! Apa yang Anda katakan, teman saya?",
  str_homestory_N19chuanshanjia_90010404_31_dialog_content = "Za! Seorang murid dengan muridnya sendiri... Sungguh, saya di hadapan para master!",
  str_homestory_N19chuanshanjia_90010404_32_dialog_content = "Saya harus kembali ke pegunungan dan berlatih selama bertahun-tahun lagi, jika saya ingin mencapai ketinggian seperti itu juga! Sampai bertemu lagi, sesama pejuang! Pamitan!",
  str_homestory_N19chuanshanjia_90010404_33_dialog_content = "Dan dia juga menunjukkan begitu banyak janji! Hari yang menyedihkan bagi militer Illumina, memang...",
  str_homestory_N19chuanshanjia_90010404_34_dialog_content = "Setelah kamp pelatihan saya dibangun, saya pasti akan merekrutnya ke dalam barisan saya! Sampai Lain waktu, PlayerName!",
  str_homestory_N19chuanshanjia_90010404_35_dialog_content = "Aku tidak percaya... Mereka akhirnya mengagumi kekuatan satu sama lain...",
  str_homestory_N19chuanshanjia_90010501_1_dialog_content = "Temanku!",
  str_homestory_N19chuanshanjia_90010501_2_dialog_content = "Hah? Apakah kamu bicara dengan ku?",
  str_homestory_N19chuanshanjia_90010501_3_dialog_content = "Dudu! Semua orang berbicara tentang bantuan Anda, jadi saya datang untuk melihat Anda juga!",
  str_homestory_N19chuanshanjia_90010501_4_dialog_content = "Biar kutebak... Namamu \"Du-Du\" atau apa, kan?",
  str_homestory_N19chuanshanjia_90010501_5_dialog_content = "Ini sebenarnya <color=#FFB400>perut hijau</color>! Dudu!",
  str_homestory_N19chuanshanjia_90010501_6_dialog_content = "Begitu... Ketika Anda mengatakan \"semua orang,\" apakah Anda mengacu pada semua Pangalo yang datang selama beberapa hari terakhir?",
  str_homestory_N19chuanshanjia_90010501_7_dialog_content = "Memang! Mereka semua merasakan rasa terima kasih yang besar terhadap Anda, jadi saya datang untuk menyampaikan tanda terima kasih itu!",
  str_homestory_N19chuanshanjia_90010501_8_dialog_content = "Tanda terima kasih? Seperti hadiah?",
  str_homestory_N19chuanshanjia_90010501_9_dialog_content = "Dudu! Minuman spesial, tepatnya! Dibuat dari resep rahasia keluarga!",
  str_homestory_N19chuanshanjia_90010501_10_dialog_content = "Dari luar mungkin terlihat biasa saja...",
  str_homestory_N19chuanshanjia_90010501_11_dialog_content = "Tetapi Anda akan mengerti betapa istimewanya saat melewati bibir Anda! Dudu!",
  str_homestory_N19chuanshanjia_90010501_12_dialog_content = "Rasanya agak hangat saat turun ke tenggorokan Anda, tetapi begitu mencapai perut Anda, seluruh tubuh Anda akan mengalami rasa nyaman yang tidak seperti apa pun yang pernah Anda rasakan...",
  str_homestory_N19chuanshanjia_90010501_13_dialog_content = "Kedengarannya cukup menarik! Apakah benar-benar ada minuman seperti itu di dunia?",
  str_homestory_N19chuanshanjia_90010501_14_dialog_content = "Dudu! Tentu saja ada! Nah, apakah Anda ingin mencoba beberapa?",
  str_homestory_N19chuanshanjia_90010501_15_dialog_content = "Tentu saja! Apa yang Anda butuhkan untuk membuatnya?",
  str_homestory_N19chuanshanjia_90010501_16_dialog_content = "Dudu! Seperti yang saya katakan, ini adalah resep rahasia keluarga!",
  str_homestory_N19chuanshanjia_90010501_17_dialog_content = "Pertama, saya perlu beberapa <color=#FFB400>garam</color>.",
  str_homestory_N19chuanshanjia_90010501_18_dialog_content = "Saya pikir saya melihat <color=#FFB400>Pedagang Chubb</color> berkeliaran di dekat hutan. Kita bisa meminta beberapa!",
  str_homestory_N19chuanshanjia_90010511_1_dialog_content = "Jam terus berdetak. Ayo cepat! Du-du.",
  str_homestory_N19chuanshanjia_90010502_1_dialog_content = "Garam? Ya, saya punya beberapa. Chubb!",
  str_homestory_N19chuanshanjia_90010502_2_dialog_content = "Seseorang telah memesan garam. Aku tidak bisa menjualnya sesukaku, Chubb.",
  str_homestory_N19chuanshanjia_90010502_3_dialog_content = "Aku hanya butuh sedikit. Tidak bisakah kamu menyisihkan sedikit?",
  str_homestory_N19chuanshanjia_90010502_4_dialog_content = "Coba saya lihat, Chubb.",
  str_homestory_N19chuanshanjia_90010502_5_dialog_content = "Seharusnya tidak apa-apa untuk memberi Anda sedikit, menurut perkiraan saya. Chubb!",
  str_homestory_N19chuanshanjia_90010502_6_dialog_content = "Itu keren!",
  str_homestory_N19chuanshanjia_90010502_7_dialog_content = "Tetapi Anda harus membuat perbedaan dengan <color=#FFB400>bijih</color>. Saya perlu meningkatkan penjualan bijih, Chubb!",
  str_homestory_N19chuanshanjia_90010502_8_dialog_content = "Bukan masalah! Kita bisa bernegosiasi!",
  str_homestory_N19chuanshanjia_90010512_1_dialog_content = "Saya bilang 10! Chubb!",
  str_homestory_N19chuanshanjia_90010503_1_dialog_content = "Cukup bijih?",
  str_homestory_N19chuanshanjia_90010503_2_dialog_content = "Di Sini! Bijih. ({1}/{2})",
  str_homestory_N19chuanshanjia_90010503_3_dialog_content = "Itu tadi cepat! Chubb!",
  str_homestory_N19chuanshanjia_90010503_4_dialog_content = "Tentu saja! PlayerName sangat akrab dengan Cloud Gardens! Chubb!",
  str_homestory_N19chuanshanjia_90010503_5_dialog_content = "Ini adalah garam. Jangan kehilangan itu. Chubb.",
  str_homestory_N19chuanshanjia_90010503_6_dialog_content = "Semua dikemas rapat dan kokoh. Jangan lemparkan itu dalam perjalanan kembali, Chubb.",
  str_homestory_N19chuanshanjia_90010503_7_dialog_content = "Terima kasih banyak!",
  str_homestory_N19chuanshanjia_90010503_8_dialog_content = "Belum.",
  str_homestory_N19chuanshanjia_90010513_1_dialog_content = "Hati-hati jangan sampai tumpah, Chubb!",
  str_homestory_N19chuanshanjia_90010504_1_dialog_content = "Ini garamnya.",
  str_homestory_N19chuanshanjia_90010504_2_dialog_content = "Itu butuh waktu lama! Dudu!",
  str_homestory_N19chuanshanjia_90010504_3_dialog_content = "Ya, itu jalan memutar yang besar. Jika bukan karena minuman misterius ini...",
  str_homestory_N19chuanshanjia_90010504_4_dialog_content = "Anda akan segera melihatnya. Saya sudah menyiapkan sisa bahannya, du-du!",
  str_homestory_N19chuanshanjia_90010504_5_dialog_content = "Mari kita memulainya!",
  str_homestory_N19chuanshanjia_90010504_6_dialog_content = "Anda akan pergi dari sini sebentar. Ini adalah resep rahasia, Anda tahu? Eksklusif! Dudu!",
  str_homestory_N19chuanshanjia_90010504_7_dialog_content = "Oh, kalau begitu biarkan aku <color=#FFB400>pergi berjalan-jalan di suatu tempat dekat</color>.",
  str_homestory_N19chuanshanjia_90010504_8_dialog_content = "Pergi untuk berjalan lebih lama! Keluar di tepi sungai itu bagus!",
  str_homestory_N19chuanshanjia_90010505_1_dialog_content = "Anda akhirnya di sini! Minuman sudah siap!",
  str_homestory_N19chuanshanjia_90010505_2_dialog_content = "Hah? Ini terlihat sangat normal. Ini transparan dan juga tidak berbau apa pun.",
  str_homestory_N19chuanshanjia_90010505_3_dialog_content = "Saya menambahkan rasa rahasia untuk itu! Jenis khusus! Anda tidak dapat melihatnya ketika dimasukkan ke dalam air.",
  str_homestory_N19chuanshanjia_90010505_4_dialog_content = "Penyedap rasa yang tidak terlihat dalam air... Apakah sekantong garam itu?",
  str_homestory_N19chuanshanjia_90010505_5_dialog_content = "Saya suka orang pintar! Dudu!",
  str_homestory_N19chuanshanjia_90010505_6_dialog_content = "Ah! Oh tidak, itu bukan lagi rahasia!",
  str_homestory_N19chuanshanjia_90010505_7_dialog_content = "Anda bilang satu-satunya penyedap dalam minuman misterius ini adalah garamnya?!",
  str_homestory_N19chuanshanjia_90010505_8_dialog_content = "Kemampuan psikismu sesuai dengan apa yang Fussy katakan padaku. Dudu!",
  str_homestory_N19chuanshanjia_90010505_9_dialog_content = "Memang, hanya garam. Du-du.",
  str_homestory_N19chuanshanjia_90010505_10_dialog_content = "<size=65>Bukankah itu hanya air asin biasa?!</size>",
  str_homestory_N19chuanshanjia_90010505_11_dialog_content = "Sst! Jangan biarkan siapa pun mendengarnya! Dudu!",
  str_homestory_N19chuanshanjia_90010505_12_dialog_content = "Jika asin, ada banyak di laut!",
  str_homestory_N19chuanshanjia_90010505_13_dialog_content = "Tapi tidak ada di pegunungan! Dudu! Yang Anda temukan di pegunungan adalah jenis air yang jernih dan tidak berasa.",
  str_homestory_N19chuanshanjia_90010505_14_dialog_content = "Suatu kali, saya berada di sebuah gua, dan saya menjilati air kental di atas batu. Itu asin.",
  str_homestory_N19chuanshanjia_90010505_15_dialog_content = "Saya menemukan rasa ini luar biasa sejak itu! Dudu!",
  str_homestory_N19chuanshanjia_90010505_16_dialog_content = "(Yah, garam adalah hal yang biasa dalam hidup kita.)",
  str_homestory_N19chuanshanjia_90010505_17_dialog_content = "(Tapi bagi mereka...)",
  str_homestory_N19chuanshanjia_90010505_18_dialog_content = "Sekarang setelah Anda menyebutkannya, saya juga menyadarinya.",
  str_homestory_N19chuanshanjia_90010505_19_dialog_content = "Garam memiliki rasa yang benar-benar luar biasa.",
  str_homestory_N19chuanshanjia_90010505_20_dialog_content = "Beritahu aku tentang itu! Saya! Dudu! Anda harus merahasiakannya!",
  str_homestory_N19chuanshanjia_90010505_21_dialog_content = "Oke oke.",
  str_homestory_N19chuanshanjia_90010505_22_dialog_content = "Saya punya banyak garam di sini. Anda dapat mampir kapan saja dan mengambilnya.",
  str_homestory_N19chuanshanjia_90010505_23_dialog_content = "Betulkah? Itu murah hati dari Anda! Dudu!",
  str_homestory_N19chuanshanjia_90010505_24_dialog_content = "Saya juga punya banyak minuman dalam rasa lain yang bisa Anda cicipi lain kali.",
  str_homestory_N19chuanshanjia_90010505_25_dialog_content = "Ya! Ya! Tapi menurut saya air asin ini tetap yang paling enak!",
  str_homestory_N19chuanshanjia_90010505_26_dialog_content = "Jika Anda tidak minum, maka saya akan mengambilnya kembali! Dudu!",
  str_homestory_N19chuanshanjia_90010505_27_dialog_content = "Hati-hati di luar sana!",
  str_homestory_N19chuanshanjia_90010505_28_dialog_content = "Salt, huh... membunyikan lonceng pada pepatah dari novel itu.",
  str_homestory_N19chuanshanjia_90010505_29_dialog_content = "\"Mencintai seseorang itu seperti mengasinkan. Tidak lebih dan tidak kurang.\"",
  str_homestory_N19chuanshanjia_90010505_30_dialog_content = "Mungkin rahasia sebenarnya dari minuman ini adalah rasio garam dan airnya.",
  str_homestory_N19chuanshanjia_90010601_1_dialog_content = "<anim type=Shake><size=65>Kematian adalah kekosongan! Kematian adalah kebenaran!</size></anim>",
  str_homestory_N19chuanshanjia_90010601_2_dialog_content = "Tempat ini terlalu berisik... Vice, Saya pergi!",
  str_homestory_N19chuanshanjia_90010601_3_dialog_content = "Apa itu? Aku tidak bisa mendengarmu dengan jelas! Yah, apa pun yang Anda katakan, saya harus pergi!",
  str_homestory_N19chuanshanjia_90010601_4_dialog_content = "Vice, tunggu!",
  str_homestory_N19chuanshanjia_90010601_5_dialog_content = "Dia pergi dengan cepat. Either way, musik di sini keras.",
  str_homestory_N19chuanshanjia_90010601_6_dialog_content = "Argh, kupikir aku bisa mengatasinya Regina's kinerja sekarang, tapi saya kira tidak.",
  str_homestory_N19chuanshanjia_90010601_7_dialog_content = "Apakah itu bahkan dianggap sebagai musik? Itu hanya suara gemuruh acak dari alat musik.",
  str_homestory_N19chuanshanjia_90010601_8_dialog_content = "Musik ini adalah kiriman dewa! Tidak ada di seluruh dunia liar! Eep!",
  str_homestory_N19chuanshanjia_90010601_9_dialog_content = "Ini tempo, melodi, aransemen, dan vokal. Saya tidak bisa melewatkannya! Eep!",
  str_homestory_N19chuanshanjia_90010601_10_dialog_content = "... Apakah kamu serius?",
  str_homestory_N19chuanshanjia_90010601_11_dialog_content = "Ya, nama musisi yang luar biasa ini adalah Regina.",
  str_homestory_N19chuanshanjia_90010601_12_dialog_content = "Ah! Tentu.",
  str_homestory_N19chuanshanjia_90010601_13_dialog_content = "Dia pasti sangat populer.",
  str_homestory_N19chuanshanjia_90010601_14_dialog_content = "Ini sedikit... Um, aku tidak tahu bagaimana mengatakannya.",
  str_homestory_N19chuanshanjia_90010601_15_dialog_content = "Maksud kamu apa? Anda tampaknya tidak menikmati musiknya.",
  str_homestory_N19chuanshanjia_90010601_16_dialog_content = "Betul sekali! Za!",
  str_homestory_N19chuanshanjia_90010601_17_dialog_content = "Sahn, Jiji, kami hanya pergi untuk mengintip.",
  str_homestory_N19chuanshanjia_90010601_18_dialog_content = "Regina tidak memiliki penonton! Du!",
  str_homestory_N19chuanshanjia_90010601_19_dialog_content = "Bagaimana ini bisa...?",
  str_homestory_N19chuanshanjia_90010601_20_dialog_content = "Itu benar! Regina sedang tampil sendirian.",
  str_homestory_N19chuanshanjia_90010601_21_dialog_content = "Sayang sekali... Jauh, tapi aku bisa merasakan ketidakpuasan di Reginabernyanyi.",
  str_homestory_N19chuanshanjia_90010601_22_dialog_content = "Dudu! Haruskah kita bersorak untuknya?",
  str_homestory_N19chuanshanjia_90010601_23_dialog_content = "Ide bagus! Eep!",
  str_homestory_N19chuanshanjia_90010601_24_dialog_content = "Tapi dia terlihat sedikit menakutkan. Bukan ide yang baik bagi kita untuk lari ke sana, kan? Gwa!",
  str_homestory_N19chuanshanjia_90010601_25_dialog_content = "Mari kita berlatih tentang cara menyemangati seseorang.",
  str_homestory_N19chuanshanjia_90010601_26_dialog_content = "PlayerName, bagaimana Aurorian bersorak untuk orang lain?",
  str_homestory_N19chuanshanjia_90010601_27_dialog_content = "Aku... Aku bisa bertanya pada seseorang. Selama aku bisa keluar dari sini...",
  str_homestory_N19chuanshanjia_90010601_28_dialog_content = "Kami akan menunggu kabar dari Anda.",
  str_homestory_N19chuanshanjia_90010601_29_dialog_content = "Sakit <color=#FFB400>pergi bertanya Vice</color>. Dia seharusnya masih ada.",
  str_homestory_N19chuanshanjia_90010602_1_dialog_content = "Fiuh, akhirnya diam.",
  str_homestory_N19chuanshanjia_90010602_2_dialog_content = "Hai, Vice! Aku butuh sesuatu darimu.",
  str_homestory_N19chuanshanjia_90010602_3_dialog_content = "Jangan bilang kamu masih ingin aku mendengarkan Reginamusik!",
  str_homestory_N19chuanshanjia_90010602_4_dialog_content = "T-Tidak, aku punya pertanyaan untukmu.",
  str_homestory_N19chuanshanjia_90010602_5_dialog_content = "Pertanyaan apa pun baik-baik saja selama tidak mendengarkan musik itu.",
  str_homestory_N19chuanshanjia_90010602_6_dialog_content = "Apa cara terbaik untuk menghibur seseorang? Lebih disukai dengan banyak orang.",
  str_homestory_N19chuanshanjia_90010602_7_dialog_content = "Kedengarannya sangat mirip dengan <color=#FFB400>mendukung</color> itu <color=#FFB400>Barbara</color> disebutkan sebelumnya.",
  str_homestory_N19chuanshanjia_90010602_8_dialog_content = "Dia kebetulan nongkrong di tepi sungai. Ingin pergi bertanya padanya?",
  str_homestory_N19chuanshanjia_90010602_9_dialog_content = "Itu keren!",
  str_homestory_N19chuanshanjia_90010603_1_dialog_content = "Memancing sangat sulit!",
  str_homestory_N19chuanshanjia_90010603_2_dialog_content = "Hai, Barbara! Keluar jalan-jalan?",
  str_homestory_N19chuanshanjia_90010603_3_dialog_content = "Aku sedang memancing! Ini tugas yang cukup sulit!",
  str_homestory_N19chuanshanjia_90010603_4_dialog_content = "Aku senang kau di sini. Apa cara terbaik untuk mendukung seseorang?",
  str_homestory_N19chuanshanjia_90010603_5_dialog_content = "Entahlah, perutku kosong sekarang!",
  str_homestory_N19chuanshanjia_90010603_6_dialog_content = "Jadi itu sebabnya kamu memancing?",
  str_homestory_N19chuanshanjia_90010603_7_dialog_content = "Saya sangat menginginkan sashimi! Tapi memancing sangat sulit!",
  str_homestory_N19chuanshanjia_90010603_8_dialog_content = "Tidak sulit untuk memancing. Biarkan aku yang melakukannya!",
  str_homestory_N19chuanshanjia_90010603_9_dialog_content = "<color=#FFB400>Tiga ikan</color> sudah cukup, kan?",
  str_homestory_N19chuanshanjia_90010603_10_dialog_content = "Sangat cukup!",
  str_homestory_N19chuanshanjia_90010604_1_dialog_content = "Ikan segar! Akan mendapatkan ikan segar!",
  str_homestory_N19chuanshanjia_90010604_2_dialog_content = "Ini cukup, kan? ({1}/{2})",
  str_homestory_N19chuanshanjia_90010604_3_dialog_content = "Ya! Sangat segar!",
  str_homestory_N19chuanshanjia_90010604_4_dialog_content = "Anda bisa makan sampai kenyang nanti. Anda bisa menjawab pertanyaan saya sekarang, kan?",
  str_homestory_N19chuanshanjia_90010604_5_dialog_content = "Jika saya ingin banyak orang menyemangati seseorang, itu <color=#FFB400>mendukung</color>, Baik?",
  str_homestory_N19chuanshanjia_90010604_6_dialog_content = "Apakah ada trik?",
  str_homestory_N19chuanshanjia_90010604_7_dialog_content = "Nya \"<color=#FFB400>cinta</color>\"!",
  str_homestory_N19chuanshanjia_90010604_8_dialog_content = "Cinta? Hanya itu?",
  str_homestory_N19chuanshanjia_90010604_9_dialog_content = "Ini sangat penting!",
  str_homestory_N19chuanshanjia_90010604_10_dialog_content = "Jika Anda menunjukkan cinta yang cukup, orang lain pasti akan merasakannya.",
  str_homestory_N19chuanshanjia_90010604_11_dialog_content = "Itu dia?",
  str_homestory_N19chuanshanjia_90010604_12_dialog_content = "Ketulusan lebih baik daripada trik apa pun!",
  str_homestory_N19chuanshanjia_90010604_13_dialog_content = "aku akan mencobanya...",
  str_homestory_N19chuanshanjia_90010604_14_dialog_content = "Aku akan memancing lagi.",
  str_homestory_N19chuanshanjia_90010605_1_dialog_content = "Dari apa yang kudengar, kalian harus cukup tulus untuk menunjukkan cinta kalian... dan memang seharusnya begitu.",
  str_homestory_N19chuanshanjia_90010605_2_dialog_content = "Tapi bagaimana cara kita mengungkapkan cinta?",
  str_homestory_N19chuanshanjia_90010605_3_dialog_content = "Menurut para profesional, pihak lain pasti akan merasakannya jika kalian sangat menyukainya.",
  str_homestory_N19chuanshanjia_90010605_4_dialog_content = "Anda hanya perlu mengekspresikan diri Anda sepenuhnya.",
  str_homestory_N19chuanshanjia_90010605_5_dialog_content = "Berbicara tentang cinta Regina memiliki musik, kita mungkin mengerti bahwa yang terbaik!",
  str_homestory_N19chuanshanjia_90010605_6_dialog_content = "Ya! Itulah semangat!",
  str_homestory_N19chuanshanjia_90010605_7_dialog_content = "Aku akan membahas penanggulangan dengan mereka. Ayo lihat dukungan kami nanti juga!",
  str_homestory_N19chuanshanjia_90010605_8_dialog_content = "aku harus kembali...?",
  str_homestory_N19chuanshanjia_90010606_1_dialog_content = "Telingaku mulai berdarah begitu aku kembali ke sini.",
  str_homestory_N19chuanshanjia_90010606_2_dialog_content = "<anim type=Shake><size=65>Dunia yang tidak adil! Hati yang membara!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_3_dialog_content = "Tapi seperti yang dikatakan Sahn. Entah itu lirik atau ritme, ada rasa dendam.",
  str_homestory_N19chuanshanjia_90010606_4_dialog_content = "Kelihatannya Regina memiliki banyak pemikiran yang ingin dia ungkapkan juga...",
  str_homestory_N19chuanshanjia_90010606_5_dialog_content = "Anda mengatakan...",
  str_homestory_N19chuanshanjia_90010606_6_dialog_content = "Musik! Jangan berhenti! Eep!",
  str_homestory_N19chuanshanjia_90010606_7_dialog_content = "Za! Kami ingin musik!",
  str_homestory_N19chuanshanjia_90010606_8_dialog_content = "Reginamusik! Yang terkuat! Du!",
  str_homestory_N19chuanshanjia_90010606_9_dialog_content = "Ini dia lagu terbarunya! Untuk semua penonton baru!",
  str_homestory_N19chuanshanjia_90010606_10_dialog_content = "<anim type=Shake><size=65>Seperti Musuh Besar Datang!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_11_dialog_content = "<anim type=Shake><size=65>Musuh yang sebenarnya bukanlah Eclipsites!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_12_dialog_content = "Benar-benar bukan Eclipsites!",
  str_homestory_N19chuanshanjia_90010606_13_dialog_content = "Benar-benar bukan Eclipsites!",
  str_homestory_N19chuanshanjia_90010606_14_dialog_content = "<anim type=Shake><size=65>Ini adalah kegelapan pikiran!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_15_dialog_content = "Kegelapan pikiran!",
  str_homestory_N19chuanshanjia_90010606_16_dialog_content = "Kegelapan! Dari pikiran!",
  str_homestory_N19chuanshanjia_90010606_17_dialog_content = "Kegelapan! Pikiran!",
  str_homestory_N19chuanshanjia_90010606_18_dialog_content = "Saya tidak menyangka Pangalo menyukai jenis musik ini.",
  str_homestory_N19chuanshanjia_90010606_19_dialog_content = "Unik rasanya...",
  str_homestory_N19chuanshanjia_90010606_20_dialog_content = "Apakah Anda mendengar solo itu di bagian terakhir? Itu sangat luar biasa!",
  str_homestory_N19chuanshanjia_90010606_21_dialog_content = "Saya penuh dengan kekuatan! Aku tak terkalahkan!",
  str_homestory_N19chuanshanjia_90010606_22_dialog_content = "Aku akan terbang!",
  str_homestory_N19chuanshanjia_90010606_23_dialog_content = "Kenapa aku menangis...?",
  str_homestory_N19chuanshanjia_90010606_24_dialog_content = "Solo itu akan terulang di kepalaku untuk bulan depan!",
  str_homestory_N19chuanshanjia_90010606_25_dialog_content = "Kalian...",
  str_homestory_N19chuanshanjia_90010606_26_dialog_content = "Saya telah melakukan banyak pertunjukan, tetapi ini adalah pertama kalinya saya memiliki penonton seperti kalian.",
  str_homestory_N19chuanshanjia_90010606_27_dialog_content = "Dan cara bersorak itu... Aku merasa pernah melihatnya di suatu tempat...",
  str_homestory_N19chuanshanjia_90010606_28_dialog_content = "Ehem, itu tidak penting. Yang penting adalah mereka sangat menyukai lagu Anda.",
  str_homestory_N19chuanshanjia_90010606_29_dialog_content = "Ya! Saya bisa merasakan ketulusan mereka melalui ekspresi dan bahasa tubuh mereka.",
  str_homestory_N19chuanshanjia_90010606_30_dialog_content = "Aah! Mereka mengelilingi kita!",
  str_homestory_N19chuanshanjia_90010606_31_dialog_content = "Regina, atas nama Lithic Pangalo, saya ingin mengucapkan terima kasih yang tulus.",
  str_homestory_N19chuanshanjia_90010606_32_dialog_content = "Tanda tangan! Tanda tangan! Eep!",
  str_homestory_N19chuanshanjia_90010606_33_dialog_content = "Boleh minta tanda tangan juga?",
  str_homestory_N19chuanshanjia_90010606_34_dialog_content = "Za! Sahn, Tubby, Perut Hijau! Berhenti berkeliaran! Ayo sekarang!",
  str_homestory_N19chuanshanjia_90010606_35_dialog_content = "Y-Ya, Nyonya Regina! Saya ingin tanda tangan juga!",
  str_homestory_N19chuanshanjia_90010606_36_dialog_content = "Haha, aku bukan wanita! Aku hanya seorang rocker!",
  str_homestory_N19chuanshanjia_90010606_37_dialog_content = "Tapi cara kalian bersorak sebelumnya...",
  str_homestory_N19chuanshanjia_90010606_38_dialog_content = "Apakah itu \"menggoreng krim puff\" mengajari Anda?",
  str_homestory_N19chuanshanjia_90010606_39_dialog_content = "Um! aku mengajari mereka...",
  str_homestory_N19chuanshanjia_90010606_40_dialog_content = "Jadi \"menggoreng krim puff\" mengajari Anda.",
  str_homestory_N19chuanshanjia_90010606_41_dialog_content = "Berbuat salah...",
  str_homestory_N19chuanshanjia_90010606_42_dialog_content = "Tetapi mereka sangat tulus, dan saya dapat mengatakan bahwa itu adalah penghargaan dari hati.",
  str_homestory_N19chuanshanjia_90010606_43_dialog_content = "Ayo! Tanda tangan tidak masalah! Foto bersama juga oke!",
  str_homestory_N19chuanshanjia_90010606_44_dialog_content = "Aku... aku akan pingsan! Pingsan! Eep!",
  str_homestory_N19chuanshanjia_90010606_45_dialog_content = "Jiji!",
  str_homestory_N19chuanshanjia_90010606_46_dialog_content = "perut hijau! Bantu aku membangunkan Jiji!",
  str_homestory_N19chuanshanjia_90010606_47_dialog_content = "Foto grup-g!",
  str_homestory_N19chuanshanjia_90010606_48_dialog_content = "Ahahaha.. Memuaskan sekali..",
  str_homestory_N19chuanshanjia_90010606_49_dialog_content = "(Saya ingin tahu apakah saya harus mengingatkan mereka bahwa tidak ada kamera di Cloud Gardens ...)",
  str_homestory_N19chuanshanjia_90010611_1_dialog_content = "Dia di tepi sungai.",
  str_homestory_N19chuanshanjia_90010612_1_dialog_content = "3 ikan... itu cukup untuk memberiku makan untuk sementara waktu!",
  str_homestory_N19chuanshanjia_90010613_1_dialog_content = "Ingat! Keikhlasan adalah kuncinya!",
  str_homestory_N19chuanshanjia_90010614_1_dialog_content = "Pergi, mereka tidak bisa menunggu lebih lama lagi.",
  str_homestory_N19chuanshanjia_90010113_1_dialog_content = "Apakah ada hewan lain yang bisa berbicara?",
  str_homestory_N19chuanshanjia_90010114_1_dialog_content = "Sudahkah kamu menemukan? Korgon?",
  str_homestory_N19chuanshanjia_90010115_1_dialog_content = "Sudah lama sekali... Apa benar ada hewan lain yang bisa berbicara?",
  str_homestory_N19chuanshanjia_90010116_1_dialog_content = "Dengan cepat! Sahn akan pergi jika Anda terlalu lambat."
}
